from pysat.solvers import Solver
from pysat.card import CardEnc

def solve_qg3(n=12):
    """
    Solve QG3 quasigroup of order n.
    Variable encoding: v(i,j,k) = i*n*n + j*n + k + 1 (1-indexed for SAT)
    """
    def var(i, j, k):
        return i * n * n + j * n + k + 1

    clauses = []

    # 1. Each cell has at least one value
    for i in range(n):
        for j in range(n):
            clauses.append([var(i, j, k) for k in range(n)])

    # 2. Each cell has at most one value
    for i in range(n):
        for j in range(n):
            for k1 in range(n):
                for k2 in range(k1 + 1, n):
                    clauses.append([-var(i, j, k1), -var(i, j, k2)])

    # 3. Latin square: each value appears exactly once per row
    for i in range(n):
        for k in range(n):
            # at least once
            clauses.append([var(i, j, k) for j in range(n)])
            # at most once
            for j1 in range(n):
                for j2 in range(j1 + 1, n):
                    clauses.append([-var(i, j1, k), -var(i, j2, k)])

    # 4. Latin square: each value appears exactly once per column
    for j in range(n):
        for k in range(n):
            # at least once
            clauses.append([var(i, j, k) for i in range(n)])
            # at most once
            for i1 in range(n):
                for i2 in range(i1 + 1, n):
                    clauses.append([-var(i1, j, k), -var(i2, j, k)])

    # 5. Idempotent: x[i][i] = i
    for i in range(n):
        clauses.append([var(i, i, i)])

    # 6. QG3: x[x[i][j]][x[j][i]] = i
    # For all i, j, k, l: if x[i][j] = k and x[j][i] = l then x[k][l] = i
    for i in range(n):
        for j in range(n):
            for k in range(n):
                for l in range(n):
                    clauses.append([-var(i, j, k), -var(j, i, l), var(k, l, i)])

    print(f"Total clauses: {len(clauses)}")

    # Solve with Glucose3
    with Solver(name='glucose3') as solver:
        for clause in clauses:
            solver.add_clause(clause)

        print("Solving...")
        sat = solver.solve()
        print(f"SAT: {sat}")

        if sat:
            model = solver.get_model()
            # Extract solution
            grid = [[0] * n for _ in range(n)]
            for lit in model:
                if lit > 0:
                    v = lit - 1
                    k = v % n
                    v //= n
                    j = v % n
                    i = v // n
                    grid[i][j] = k
            return grid
        else:
            return None

